mapper.update:
UPDATE cron_job_locks
SET owner_id = #{ownerId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler},
    lock_until = #{lockUntil}
WHERE job_name = #{jobName}
  AND lock_until <= #{now}

UPDATE cron_job_locks
SET lock_until = #{lockUntil}
WHERE job_name = #{jobName}
  AND owner_id = #{ownerId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}

mapper.delete:
DELETE FROM cron_job_locks
WHERE job_name = #{jobName}
  AND owner_id = #{ownerId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}
